messages:
[
  {
    "from": "them",
    "kind": "text",
    "sender": "אבא",
    "text": "בוקר טוב, לקחתי את האוטו למוסך"
  },
  {
    "from": "me",
    "kind": "text",
    "sender": null,
    "text": "תודה רבה! אמרו כמה זמן?"
  },
  {
    "from": "them",
    "kind": "text",
    "sender": "אבא",
    "text": "אמרו עד אחר הצהריים"
  },
  {
    "from": "them",
    "kind": "text",
    "sender": "אבא",
    "text": "שלום, סידרתי את העניין עם המוסך"
  },
  {
    "from": "me",
    "kind": "text",
    "sender": null,
    "text": "תודה! כמה יצא בסוף?"
  },
  {
    "from": "them",
    "kind": "text",
    "sender": "אבא",
    "text": "1,240 כולל הבלמים. הם נתנו הנחה"
  },
  {
    "from": "me",
    "kind": "text",
    "sender": null,
    "text": "מעולה, אני אעביר לך הערב"
  },
  {
    "from": "them",
    "kind": "text",
    "sender": "אבא",
    "text": "אין לחץ"
  },
  {
    "from": "them",
    "kind": "text",
    "sender": "אבא",
    "text": "אתה מגיע לארוחת ערב בשישי? אמא שואלת"
  },
  {
    "from": "me",
    "kind": "text",
    "sender": null,
    "text": "כן, נגיע בסביבות שבע"
  },
  {
    "from": "me",
    "kind": "text",
    "sender": null,
    "text": "אני מביא יין"
  }
]
